// Claude 응답 → { ok, data } 또는 { ok: false, error_* } (14.11 오류 분류). 예외를 던지지 않는다.
const r = $input.first().json;
const out = (o) => [{ json: o }];
if (typeof r.statusCode !== 'number') return out({ ok: false, error_type: 'transient', error_code: 'NETWORK_ERROR', message: String(r.error?.message || 'LLM request failed').slice(0, 500), retryable: true });
const s = r.statusCode, b = r.body || {};
if (s === 429 || s === 529) {
  const ra = Number(r.headers?.['retry-after']);
  return out({ ok: false, error_type: 'api', error_code: 'RATE_LIMIT', message: `LLM ${s}`, retryable: true, retry_after: Number.isFinite(ra) && ra > 0 ? Math.ceil(ra) : null });
}
if (s >= 500 || s === 408 || s === 409) return out({ ok: false, error_type: 'api', error_code: 'TEMPORARY_API_ERROR', message: `LLM ${s}`, retryable: true });
if (s === 401 || s === 403) return out({ ok: false, error_type: 'authentication', error_code: 'INVALID_AUTH', message: `LLM ${s}: check the PA Anthropic credential`, retryable: false });
if (s >= 400) return out({ ok: false, error_type: 'api', error_code: 'LLM_REQUEST_INVALID', message: `LLM ${s}: ${JSON.stringify(b.error || b).slice(0, 300)}`, retryable: false });
if (b.stop_reason === 'refusal') return out({ ok: false, error_type: 'policy', error_code: 'POLICY_ERROR', message: `LLM declined (${b.stop_details?.category ?? 'no category'})`, retryable: false });
if (b.stop_reason === 'max_tokens') return out({ ok: false, error_type: 'validation', error_code: 'LLM_OUTPUT_INVALID', message: 'LLM output was cut off (max_tokens)', retryable: true });
const text = (b.content || []).filter((c) => c.type === 'text').map((c) => c.text).join('');
let data;
try { data = JSON.parse(text); } catch (e) { return out({ ok: false, error_type: 'validation', error_code: 'LLM_OUTPUT_INVALID', message: 'LLM output is not valid JSON', retryable: true }); }
return out({ ok: true, data, model: b.model, usage: { input_tokens: b.usage?.input_tokens ?? null, output_tokens: b.usage?.output_tokens ?? null } });

// 가짜 LLM (M3 완료 조건: 고정 JSON). 실제 LLM과 같은 { ok, data } 형식으로 돌려준다.
const input = $input.first().json;
const fixtures = {
  'prompt_generation.v1': {
    schema_version: 'prompt_generation.v1',
    prompt_parts: {
      subject: 'young Korean woman',
      appearance: 'long dark brown hair, natural makeup',
      outfit: 'cream knit sweater',
      location: 'modern Seoul cafe',
      action: 'sitting at a window table holding a latte',
      camera: '35mm portrait photography',
      lighting: 'soft natural window light',
      mood: 'calm',
      style: 'photorealistic, realistic skin texture, high detail'
    },
    negative_additions: ['text', 'watermark']
  },
  'caption_generation.v1': {
    schema_version: 'caption_generation.v1',
    caption: '오늘은 창가 자리에서 라떼 한 잔 ☕ 여러분의 오후는 어떤가요?',
    hashtags: ['카페', '서울카페', '일상'],
    language: 'ko'
  }
};
const data = fixtures[input.schema_version];
if (!data) return [{ json: { ok: false, error_type: 'validation', error_code: 'LLM_REQUEST_INVALID', message: `no fake fixture for ${input.schema_version}`, retryable: false } }];
return [{ json: { ok: true, data, model: 'fake', usage: null } }];
